const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7'); # You must include this line

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const gaul = ee.FeatureCollection('FAO/GAUL_SIMPLIFIED_500m/2015/level1')
      .filter(ee.Filter.eq('ADM0_NAME', 'Indonesia'));

    // Provinces by island
    const sumatraNames = [
      'Aceh','Sumatera Utara','Sumatera Barat','Riau','Kepulauan Riau',
      'Jambi','Sumatera Selatan','Bengkulu','Lampung','Kepulauan Bangka Belitung'
    ];
    const kalimantanNames = [
      'Kalimantan Barat','Kalimantan Tengah','Kalimantan Selatan','Kalimantan Timur','Kalimantan Utara'
    ];

    const sumatra = gaul.filter(ee.Filter.inList('ADM1_NAME', sumatraNames)).geometry();
    const kalimantan = gaul.filter(ee.Filter.inList('ADM1_NAME', kalimantanNames)).geometry();
    const combined = sumatra.union(kalimantan, 1);

    const years = [2022, 2023];
    const datasetPrimary = 'MODIS/061/MOD14A1';
    const datasetFallback = 'MODIS/061/MOD14A2';
    const bandName = 'FireMask';
    const scale = 1000;
    const maxPixels = 1e9;

    // Helper to wrap getInfo in a Promise
    const getInfo = (obj) => new Promise((resolve, reject) => {
      obj.getInfo((res, err) => (err ? reject(err) : resolve(res)));
    });

    async function buildYearImages(year) {
      const start = `${year}-01-01`;
      const end = `${year}-12-31`;
      let col = ee.ImageCollection(datasetPrimary).filterDate(start, end).filterBounds(combined);
      let size = await getInfo(col.size());
      if (size === 0) {
        // Try fallback
        col = ee.ImageCollection(datasetFallback).filterDate(start, end).filterBounds(combined);
        size = await getInfo(col.size());
        if (size === 0) {
          console.log(`Year ${year}: No images in primary or fallback.`);
          console.log('C1');
          return {status: 'C1'};
        }
      }
      const fireCol = col.map(img => img.select(bandName).gte(5).rename('fire').updateMask(img.select(bandName).mask()));
      const sumImg = fireCol.sum().rename('fireCount');
      return {status: 'OK', size, sumImg};
    }

    // Build yearly images
    const y22 = await buildYearImages(2022);
    if (y22.status !== 'OK') return;
    const y23 = await buildYearImages(2023);
    if (y23.status !== 'OK') return;

    // Reduce stats function
    async function statsFor(img, geom) {
      const reducers = ee.Reducer.sum().combine({reducer2: ee.Reducer.count(), sharedInputs: true});
      const resultDict = img.reduceRegion({reducer: reducers, geometry: geom, scale, maxPixels});
      const sum = await getInfo(resultDict.get('fireCount_sum'));
      const count = await getInfo(resultDict.get('fireCount_count'));
      return {sum, count};
    }

    // Compute stats per region and combined
    const [s22, k22, c22] = await Promise.all([
      statsFor(y22.sumImg, sumatra),
      statsFor(y22.sumImg, kalimantan),
      statsFor(y22.sumImg, combined)
    ]);
    const [s23, k23, c23] = await Promise.all([
      statsFor(y23.sumImg, sumatra),
      statsFor(y23.sumImg, kalimantan),
      statsFor(y23.sumImg, combined)
    ]);

    // C2 check: No valid pixels
    if ((c22.count === 0) || (c23.count === 0)) {
      console.log('No valid pixels after processing.');
      console.log('C2');
      return;
    }
    // C3 check: invalid results
    const invalid = (v) => v === null || Number.isNaN(v) || !isFinite(v);
    if (invalid(s22.sum) || invalid(k22.sum) || invalid(c22.sum) ||
        invalid(s23.sum) || invalid(k23.sum) || invalid(c23.sum)) {
      console.log('Calculation failure (null/NaN).');
      console.log('C3');
      return;
    }

    // Prepare outputs
    const fmt = (n) => Number(n).toLocaleString('en-US');
    const delta = c23.sum - c22.sum;
    const pct = c22.sum > 0 ? (delta / c22.sum) * 100 : null;

    console.log(`Dataset: ${datasetPrimary} (fallback: ${datasetFallback}), FireMask>=5`);
    console.log(`Images 2022: ${fmt(y22.size)}; 2023: ${fmt(y23.size)}`);
    console.log(`Valid px (1km) Combined 2022: ${fmt(c22.count)}; 2023: ${fmt(c23.count)}`);
    console.log(`Sumatra detections 2022: ${fmt(s22.sum)}; 2023: ${fmt(s23.sum)}`);
    console.log(`Kalimantan (Indonesian Borneo) detections 2022: ${fmt(k22.sum)}; 2023: ${fmt(k23.sum)}`);
    console.log(`Combined detections 2022: ${fmt(c22.sum)}; 2023: ${fmt(c23.sum)}; Δ: ${fmt(delta)} (${pct === null ? 'n/a' : pct.toFixed(1) + '%'})`);

    // Final Answer
    const answer = c23.sum > c22.sum ? 'A' : 'B';
    console.log(answer);

  } catch (err) {
    console.log(`Error: ${err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
